def _obj_text(code):
    from curriculum_v2.objectives import OBJECTIVES
    o = OBJECTIVES.get(code)
    return o['text'] if o else ''


def _stem_ok(key, original_text):
    rv = REVIEW.get(key)
    if not rv:
        return None
    if not ' '.join((original_text or '').split()).startswith(rv['stem']):
        MISMATCHES.append(key)
        return None
    return rv


def _revise(options, correct, rv, shift):
    """Return (options, correct) after applying a review entry. The key's slot rotates with ``shift``,
    so key positions stay balanced across a bank (the original chapter checks had 85 of 130 keys in B)."""
    rv = rv or {'wrong': None, 'correct': None}
    wrong = list(rv['wrong']) if rv['wrong'] else [o for o in options if o != correct]
    key = rv['correct'] or correct
    opts = wrong[:3] + [key]
    shift %= 4
    return opts[shift:] + opts[:shift], key


def review_bank(name, pool):
    """Apply the review to a question_bank pool (A1…N3). Returns new dicts; the source list is untouched."""
    out = []
    for i, q in enumerate(pool):
        key = f'{name}.{i}'
        rv = _stem_ok(key, q.get('text'))
        q = dict(q)
        q['bank_id'] = key
        if rv:
            q['options'], q['correct'] = _revise(q['options'], q['correct'], rv, i)
            if rv['text']:
                q['text'] = rv['text']
            q['obj'] = rv['obj']
            q['obj_text'] = _obj_text(rv['obj'])
            q['explanation'] = rv['why'] or q.get('explanation', '')
            q['review'] = rv['fix'] or 'reviewed, no change'
        out.append(q)
    return out


def review_check(order, i, item):
    """Apply the review to one pilot_slice chapter-check item (raw ``_q`` dict). Returns a new dict."""
    key = f'Q{order}.{i}'
    rv = _stem_ok(key, item.get('q'))
    q = dict(item)
    q['bank_id'] = key
    if rv:
        q['options'], q['correct'] = _revise(q['options'], q['correct'], rv, i + order)
        if rv['text']:
            q['q'] = rv['text']
        q['obj'] = rv['obj']
        q['obj_text'] = _obj_text(rv['obj'])
        q['review'] = rv['fix'] or 'reviewed, no change'
    q['explanation'] = (rv and rv['why']) or _RAT15.get(key) or _r4.served(key) or item.get('study_tip') or ''
    if not (rv and rv['why']) and key not in _RAT15 and key in _r4.RATIONALE:
        # content round 4: full rationale for the last one-line chapter-check rationales, Pending SME review
        q['review'] = '; '.join(x for x in (q.get('review'), _r4.FIX) if x)
    # pass 15: option-length parity (curriculum_v2/parity_pass15.py), text replaced in place
    from curriculum_v2 import parity_pass15
    q['options'], q['correct'] = parity_pass15.apply(key, q['options'], q['correct'])
    return q


